n = int(input())
s = list(input())
w = list(map(int, input().split()))

people = []
for i in range(n):
    people.append((w[i], s[i]))
people.sort()

ans = 0
correct_adults = 0
correct_children = 0

for w, s in people:
    if s == '1':
        correct_adults += 1
    else:
        correct_children += 1

for i in range(n):
    w, s = people[i]

    if s == '1':
        correct_adults -= 1
    else:
        correct_children -= 1

    ans = max(ans, correct_adults + correct_children)

print(ans)

