s = list(input())
w = list(map(int, input().split()))

people = []
cnt = 0
for i in range(n):
    people.append((w[i], s[i]))
    if s[i] == '1':
        cnt += 1
people.sort()

ans = cnt
for i in range(n):
    w, s = people[i]

    if s == '0':
        cnt -= 1
